def check(conf, token, prev, next, nextnext, context):
    if prev and isinstance(prev, yaml.tokens.TagToken):
        return

    if conf["forbid-implicit-octal"]:
        if isinstance(token, yaml.tokens.ScalarToken):
            if not token.style:
                val = token.value
                # Skip decimal numbers entirely
                if "." in val:
                    pass
                elif (val.isdigit() and len(val) > 1 and val[0] == "0" and
                        IS_OCTAL_NUMBER_PATTERN.match(val[1:])):
                    yield LintProblem(
                        token.start_mark.line + 1, token.end_mark.column + 1,
                        f"forbidden implicit octal value \"{token.value}\"")

    if conf["forbid-explicit-octal"]:
        if isinstance(token, yaml.tokens.ScalarToken):
            if not token.style:
                val = token.value
                # Skip decimal numbers entirely
                if "." in val:
                    pass
                elif (len(val) > 2 and val[:2] == "0o" and
                        IS_OCTAL_NUMBER_PATTERN.match(val[2:])):
                    yield LintProblem(
                        token.start_mark.line + 1, token.end_mark.column + 1,
                        f"forbidden explicit octal value \"{token.value}\"")' yamllint/rules/octal_values.py
